attributes.visState:
{"title": "[Tropobeat] CCI ops: top likely interferers, 7 days", "type": "vega", "aggs": [], "params": {"spec": "{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "autosize": {
  "type": "fit",
  "contains": "padding"
 },
 "padding": {
  "left": 20,
  "right": 20,
  "top": 18,
  "bottom": 12
 },
 "background": "#0F1F2C",
 "config": {
  "view": {
   "stroke": null
  },
  "legend": {
   "labelColor": "#8DA2B2",
   "labelFont": "ui-monospace,Menlo,Consolas,monospace",
   "labelFontSize": 11.5,
   "symbolType": "square",
   "symbolSize": 100,
   "symbolStrokeWidth": 0,
   "columnPadding": 14,
   "layout": {
    "top": {
     "anchor": "end"
    }
   }
  },
  "text": {
   "font": "\"Inter\",\"Segoe UI\",system-ui,sans-serif",
   "fill": "#E4EDF3"
  }
 },
 "title": {
  "text": "Top likely interferers, 7 days",
  "subtitle": "CONFIRMED CCI · HOURS AS THE LIKELY INTERFERER",
  "anchor": "start",
  "frame": "group",
  "offset": 12,
  "color": "#E4EDF3",
  "font": "\"Barlow Condensed\",\"Roboto Condensed\",\"Arial Narrow\",sans-serif",
  "fontSize": 22,
  "fontWeight": 600,
  "subtitleColor": "#8DA2B2",
  "subtitleFont": "ui-monospace,Menlo,Consolas,monospace",
  "subtitleFontSize": 11,
  "subtitlePadding": 4
 },
 "signals": [
  {
   "name": "rowh",
   "value": 54
  }
 ],
 "data": [
  {
   "name": "intRaw",
   "format": {
    "property": "aggregations.cs.buckets"
   },
   "url": {
    "index": "tropobeat-*",
    "body": {
     "size": 0,
     "aggs": {
      "cs": {
       "terms": {
        "field": "tropobeat.correlation.ducting.strongest.call_sign",
        "size": 30
       },
       "aggs": {
        "ep": {
         "cardinality": {
          "field": "tropobeat.correlation.episode.id"
         }
        },
        "eps": {
         "terms": {
          "field": "tropobeat.correlation.episode.id",
          "size": 1000
         },
         "aggs": {
          "dur": {
           "max": {
            "field": "tropobeat.correlation.episode.duration_s"
           }
          }
         }
        },
        "top": {
         "top_hits": {
          "size": 1,
          "sort": [
           {
            "@timestamp": "desc"
           }
          ],
          "_source": false,
          "fields": [
           "tropobeat.lrf_codes",
           "tropobeat.rf_channels",
           "tropobeat.correlation.ducting.strongest.distance_mi"
          ]
         }
        }
       }
      }
     },
     "query": {
      "bool": {
       "must": [
        "%dashboard_context-must_clause%",
        {
         "range": {
          "@timestamp": {
           "gte": "now-7d"
          }
         }
        },
        {
         "term": {
          "metricset.name": "correlation"
         }
        },
        {
         "term": {
          "tropobeat.correlation.state": "cci_confirmed"
         }
        }
       ],
       "must_not": [
        "%dashboard_context-must_not_clause%"
       ],
       "filter": [
        "%dashboard_context-filter_clause%"
       ]
      }
     }
    }
   }
  },
  {
   "name": "intSecs",
   "source": "intRaw",
   "transform": [
    {
     "type": "flatten",
     "fields": [
      "eps.buckets"
     ],
     "as": [
      "e"
     ]
    },
    {
     "type": "aggregate",
     "groupby": [
      "key"
     ],
     "fields": [
      "e.dur.value"
     ],
     "ops": [
      "sum"
     ],
     "as": [
      "secs"
     ]
    }
   ]
  },
  {
   "name": "inter",
   "source": "intRaw",
   "transform": [
    {
     "type": "lookup",
     "from": "intSecs",
     "key": "key",
     "fields": [
      "key"
     ],
     "values": [
      "secs"
     ],
     "as": [
      "secs"
     ],
     "default": 0
    },
    {
     "type": "formula",
     "as": "f",
     "expr": "datum.top.hits.hits[0].fields"
    },
    {
     "type": "formula",
     "as": "into",
     "expr": "'into ' + datum.f['tropobeat.lrf_codes'][0] + ' RF ' + datum.f['tropobeat.rf_channels'][0] + ' · ' + round(datum.f['tropobeat.correlation.ducting.strongest.distance_mi'][0]) + ' mi'"
    },
    {
     "type": "formula",
     "as": "hours",
     "expr": "datum.secs / 3600"
    },
    {
     "type": "formula",
     "as": "n",
     "expr": "datum.ep.value"
    },
    {
     "type": "window",
     "sort": {
      "field": [
       "hours",
       "n"
      ],
      "order": [
       "descending",
       "descending"
      ]
     },
     "ops": [
      "row_number"
     ],
     "as": [
      "rank"
     ]
    },
    {
     "type": "filter",
     "expr": "datum.rank <= 5"
    },
    {
     "type": "formula",
     "as": "y",
     "expr": "(datum.rank - 1) * rowh"
    },
    {
     "type": "extent",
     "field": "hours",
     "signal": "hext"
    }
   ]
  }
 ],
 "marks": [
  {
   "type": "text",
   "from": {
    "data": "inter"
   },
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "y": {
      "signal": "datum.y + 15"
     },
     "text": {
      "field": "key"
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 14
     },
     "fontWeight": {
      "value": 500
     },
     "fill": {
      "value": "#E4EDF3"
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "inter"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "length(datum.key) * 8.6 + 8"
     },
     "y": {
      "signal": "datum.y + 15"
     },
     "text": {
      "field": "into"
     },
     "limit": {
      "signal": "width - length(datum.key) * 8.6 - 70"
     },
     "fontSize": {
      "value": 14
     },
     "fill": {
      "value": "#8DA2B2"
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "inter"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "width"
     },
     "y": {
      "signal": "datum.y + 15"
     },
     "align": {
      "value": "right"
     },
     "text": {
      "signal": "format(datum.hours, '.1f') + ' h'"
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 14
     },
     "fill": {
      "value": "#C3D1DB"
     }
    }
   }
  },
  {
   "type": "rect",
   "from": {
    "data": "inter"
   },
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "x2": {
      "signal": "width"
     },
     "y": {
      "signal": "datum.y + 22"
     },
     "height": {
      "value": 8
     },
     "fill": {
      "value": "#0B1824"
     },
     "cornerRadius": {
      "value": 4
     }
    }
   }
  },
  {
   "type": "rect",
   "from": {
    "data": "inter"
   },
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "width": {
      "signal": "datum.hours > 0 ? max(8, datum.hours / hext[1] * width) : 0"
     },
     "y": {
      "signal": "datum.y + 22"
     },
     "height": {
      "value": 8
     },
     "fill": {
      "value": "#FF6B5E"
     },
     "cornerRadius": {
      "value": 4
     },
     "tooltip": {
      "signal": "{title: datum.key + ' ' + datum.into, 'Hours as likely interferer': format(datum.hours, '.1f'), 'Episodes': datum.n}"
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "inter"
   },
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "y": {
      "signal": "datum.y + 46"
     },
     "text": {
      "signal": "datum.n + (datum.n == 1 ? ' episode' : ' episodes')"
     },
     "fontSize": {
      "value": 12
     },
     "fill": {
      "value": "#8DA2B2"
     }
    }
   }
  },
  {
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "y": {
      "value": 20
     },
     "fontSize": {
      "value": 13
     },
     "fill": {
      "value": "#8DA2B2"
     },
     "text": {
      "signal": "length(data('inter')) ? '' : 'No confirmed CCI in the last 7 days'"
     }
    }
   }
  }
 ]
}"}}
